int main() {
    long long n;
    if (!(cin >> n)) return 0;

    // The maximum number of games the winner can play is the largest k
    // such that the minimum number of players required to have a winner
    // with k wins is <= n.

    // Let f(k) be the minimum number of players needed for a tournament
    // where the winner plays exactly k games.
    // The winner must beat k opponents.
    // To maximize the winner's games, we want the opponents to have
    // played as few games as possible (ideally 0), but the rule restricts
    // the difference in games played to at most 1.

    // Actually, a known result for this problem (Codeforces 138A - "Tennis Tournament" or similar variations)
    // relates to the Fibonacci sequence.

    // Let's derive it:
    // Let M(k) be the minimum number of players required so that the winner
    // can play k games.
    // For the winner to play the k-th game, he must have played k-1 games before.
    // His opponent in the k-th game must have played either k-1 or k-2 games
    // (since the difference must be <= 1).
    // To minimize the total number of players, we should choose the opponent
    // with the minimum required players for their respective game count.
    // The opponent could have played k-1 games (requiring M(k-1) players)
    // or k-2 games (requiring M(k-2) players).
    // However, the winner himself has played k-1 games before this final match.
    // So the winner's subtree requires M(k-1) players.
    // The opponent's subtree requires M(k-1) or M(k-2) players.
    // To minimize the total, we pick the smaller one for the opponent.
    // So M(k) = M(k-1) + min(M(k-1), M(k-2)) = M(k-1) + M(k-2) ?
    // Wait, if the opponent has played k-1 games, the difference is 0.
    // If the opponent has played k-2 games, the difference is 1.
    // Both are valid.
    // So M(k) = M(k-1) + min(M(k-1), M(k-2)).
    // Since M is increasing, M(k-2) < M(k-1).
    // So M(k) = M(k-1) + M(k-2).

    // Base cases:
    // M(0) = 1 (winner plays 0 games, just 1 player)
    // M(1) = 2 (winner plays 1 game, needs 1 opponent with 0 games. 1+1=2)
    // M(2) = M(1) + M(0) = 2 + 1 = 3.
    //   Winner played 1 game. Opponent must have played 0 or 1.
    //   If opponent played 0: total players = M(1) [for winner's path] + M(0) [for opponent] = 2 + 1 = 3.
    //   If opponent played 1: total players = M(1) + M(1) = 2 + 2 = 4.
    //   Min is 3.
    // M(3) = M(2) + M(1) = 3 + 2 = 5.
    // M(4) = M(3) + M(2) = 5 + 3 = 8.
    // M(5) = 8 + 5 = 13.

    // So M(k) follows the Fibonacci sequence:
    // M(0) = 1
    // M(1) = 2
    // M(2) = 3
    // M(3) = 5
    // M(4) = 8
    // M(5) = 13
    // ...
    // M(k) = Fib(k+2) if we define Fib(0)=0, Fib(1)=1, Fib(2)=1, Fib(3)=2, Fib(4)=3, Fib(5)=5...
    // Let's check:
    // Fib(2) = 1 -> M(0)=1? No.
    // Let's just generate the sequence.

    vector<long long> minPlayers;
    minPlayers.push_back(1); // k=0
    minPlayers.push_back(2); // k=1

    long long k = 1;
    while (true) {
        long long next = minPlayers[k] + minPlayers[k-1];
        if (next > n) {
            break;
        }
        minPlayers.push_back(next);
        k++;
    }

    // The maximum k such that minPlayers[k] <= n is the answer.
    // Note: minPlayers[0] corresponds to 0 games.
    // We want the max games, which is the index in the vector.

    cout << k << endl;

    return 0;
}

