#include <algorithm>

using namespace std;

int main() {
    long long n;
    cin >> n;

    // We want to find the maximum number of games the winner can play.
    // Let's think about this differently.
    // The winner plays some number of games, say k.
    // In each game, the winner plays against someone who has played either k-1, k, or k+1 games? No.
    // The rule is: two players can play if the difference in their games played is at most 1.
    // Let the winner have played k games total.
    // Consider the sequence of opponents the winner faced.
    // Let g_i be the number of games opponent i has played before facing the winner.
    // The winner has played i-1 games before facing opponent i.
    // So |g_i - (i-1)| <= 1.
    // Also, opponent i must have won all g_i games to be in the tournament.
    // This means opponent i eliminated g_i other players.
    // So the total number of players eliminated by the winner's opponents is sum(g_i).
    // Plus the winner himself, and the opponents themselves.
    // Total players n = 1 (winner) + k (opponents) + sum(g_i) (players eliminated by opponents).
    // So n = 1 + k + sum(g_i).
    // We want to maximize k.
    // We need to choose g_1, g_2, ..., g_k such that:
    // 1. g_i >= 0 (integer)
    // 2. |g_i - (i-1)| <= 1  =>  g_i >= i-2 and g_i <= i
    // 3. sum(g_i) = n - 1 - k
    // We want to maximize k.

    // For a fixed k, what is the minimum possible sum(g_i)?
    // g_i >= max(0, i-2)
    // min_sum = sum_{i=1}^{k} max(0, i-2)
    // For i=1: max(0, -1) = 0
    // For i=2: max(0, 0) = 0
    // For i=3: max(0, 1) = 1
    // For i=4: max(0, 2) = 2
    // ...
    // For i=j: max(0, j-2) = j-2 for j>=3
    // min_sum = 0 + 0 + 1 + 2 + ... + (k-2) = (k-2)(k-1)/2 for k>=2
    // For k=1: min_sum = 0
    // For k=2: min_sum = 0

    // What is the maximum possible sum(g_i)?
    // g_i <= i
    // max_sum = sum_{i=1}^{k} i = k(k+1)/2

    // So for a given k, we need:
    // min_sum <= n - 1 - k <= max_sum
    // i.e., min_sum + 1 + k <= n <= max_sum + 1 + k

    // We want the maximum k such that there exists a valid configuration.
    // Since n can be up to 10^18, k can be up to about sqrt(2n) ~ 1.4 * 10^9.
    // We can binary search on k.

    // Let's define a function to check if k is valid.
    // min_sum(k):
    // if k == 1: 0
    // if k == 2: 0
    // if k >= 3: (k-2)(k-1)/2

    // max_sum(k) = k(k+1)/2

    // Condition: min_sum(k) <= n - 1 - k <= max_sum(k)
    // i.e., min_sum(k) + k + 1 <= n <= max_sum(k) + k + 1

    auto min_sum = [](long long k) -> long long {
        if (k <= 2) return 0;
        return (k - 2) * (k - 1) / 2;
    };

    auto max_sum = [](long long k) -> long long {
        return k * (k + 1) / 2;
    };

    auto is_valid = [&](long long k) -> bool {
        long long min_needed = min_sum(k) + k + 1;
        long long max_needed = max_sum(k) + k + 1;
        return n >= min_needed && n <= max_needed;
    };

    // Binary search for the maximum k.
    // k is at least 1.
    // Upper bound: max_sum(k) + k + 1 >= n => k(k+1)/2 + k + 1 >= n => k^2/2 + 3k/2 + 1 >= n
    // k^2 ~ 2n => k ~ sqrt(2n)
    // Let's set high to something safe, like 2 * sqrt(2 * n) or just 2e9.
    // Actually, k(k+1)/2 + k + 1 >= n.
    // k^2/2 + 3k/2 + 1 >= n
    // k^2 + 3k + 2 >= 2n
    // k ~ sqrt(2n)
    // For n = 10^18, sqrt(2*10^18) ~ 1.4 * 10^9.
    // Let's use high = 2000000000LL (2e9).

    long long low = 1;
    long long high = 2000000000LL;
    long long ans = 1;

    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (is_valid(mid)) {
            ans = mid;
            low = mid + 1;
        } else {
            // If not valid, it could be that n is too small or too large for this k.
            // But we are looking for max k.
            // If n < min_needed, then k is too large (needs more players).
            // If n > max_needed, then k is too small (can accommodate more players).
            // Wait, the condition is min_needed <= n <= max_needed.
            // If n < min_needed, then k is too big. We should try smaller k.
            // If n > max_needed, then k is too small. We should try bigger k.
            // But we are binary searching for the MAX k that is valid.
            // The valid k's might not be contiguous?
            // Let's check:
            // min_needed(k) is increasing with k.
            // max_needed(k) is increasing with k.
            // So if n < min_needed(k), then for any k' > k, min_needed(k') > min_needed(k) > n, so k' is also invalid (too big).
            // If n > max_needed(k), then for any k' < k, max_needed(k') < max_needed(k) < n, so k' is also invalid (too small).
            // So the set of valid k's is an interval [k_min, k_max].
            // We want k_max.
            // If is_valid(mid) is true, we try larger k.
            // If is_valid(mid) is false:
            //   If n < min_needed(mid), then mid is too big, so high = mid - 1.
            //   If n > max_needed(mid), then mid is too small, so low = mid + 1.

            long long min_needed = min_sum(mid) + mid + 1;
            long long max_needed = max_sum(mid) + mid + 1;
            if (n < min_needed) {
                high = mid - 1;
            } else { // n > max_needed
                low = mid + 1;
            }
        }
    }

    cout << ans << endl;

    return 0;
}
