```cpp
#include <iostream>
using namespace std;

int main() {
    long long n;
    cin >> n;

    // The maximum number of games the winner can play is the largest k
    // such that the minimum number of players needed for a winner to play k games
    // is <= n.

    // Let f(k) be the minimum number of players needed so that the winner plays exactly k games.
    // For the winner to play k games, in the last game, the winner (who has played k-1 games)
    // plays against someone who has played either k-1 or k-2 games.
    // To minimize total players, we want the opponent to have played as few games as possible,
    // which is k-2 (since the difference must be at most 1).
    // So f(k) = 1 + f(k-1) + f(k-2)
    // Base cases:
    // f(0) = 1 (a player who hasn't played any games)
    // f(1) = 2 (winner plays 1 game: 2 players)
    // f(2) = 1 + f(1) + f(0) = 1 + 2 + 1 = 4
    // f(3) = 1 + f(2) + f(1) = 1 + 4 + 2 = 7
    // f(4) = 1 + f(3) + f(2) = 1 + 7 + 4 = 12
    // f(5) = 1 + f(4) + f(3) = 1 + 12 + 7 = 20
    // f(6) = 1 + f(5) + f(4) = 1 + 20 + 12 = 33
    // f(7) = 1 + f(6) + f(5) = 1 + 33 + 20 = 54
    // f(8) = 1 + f(7) + f(6) = 1 + 54 + 33 = 88
    // f(9) = 1 + f(8) + f(7) = 1 + 88 + 54 = 143
    // f(10) = 1 + f(9) + f(8) = 1 + 143 + 88 = 232

    // We need to find the maximum k such that f(k) <= n.

    // Since n can be up to 10^18, we can just iterate until f(k) > n.
    // The sequence grows roughly like Fibonacci, so it will reach 10^18 in about 90 steps.

    if (n == 1) {
        cout << 0 << endl;
        return 0;
    }

    long long f0 = 1; // f(0)
    long long f1 = 2; // f(1)

    if (n < f1) {
        cout << 0 << endl;
        return 0;
    }

    int k = 1;
    while (true) {
        long long f2 = 1 + f1 + f0; // f(k+1)
        if (f2 > n) {
            break;
        }
        f0 = f1;
        f1 = f2;
        k++;
    }

    cout << k << endl;

    return 0;
}
